import{_ as t,o,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年9月20日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-20.md","filePath":"science-log/src/reconstructed/2026-09-20.md"}'),s={name:"science-log/src/reconstructed/2026-09-20.md"};function a(g,r,i,l,c,h){return o(),n("div",null,[...r[0]||(r[0]=[e('<h1 id="🔬-科学快报-2026年9月20日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月20日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月20日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月20日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-20 为<strong>周日</strong>，Nature（0028-0836）/ Science 系（10.1126）/ PNAS（0027-8424）的 CrossRef <strong>当日命中均为 0 条</strong>（期刊周末不刊出）。故科学 5 篇取自<strong>最近的刊出窗口 2026-09-16 ~ 2026-09-17</strong>（Science 2026-09-17 期 / PNAS），并逐条标注实际出版日；AI 5 篇取自当日 arXiv cs.AI 提交（submittedDate 命中 91 篇）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609200000 TO 202609202359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-胚系-egfr-t790m-突变显著升高肺癌风险-源自一次美国南部奠基者事件" tabindex="-1">🧬 胚系 EGFR T790M 突变显著升高肺癌风险，源自一次美国南部奠基者事件 <a class="header-anchor" href="#🧬-胚系-egfr-t790m-突变显著升高肺癌风险-源自一次美国南部奠基者事件" aria-label="Permalink to &quot;🧬 胚系 EGFR T790M 突变显著升高肺癌风险，源自一次美国南部奠基者事件&quot;">​</a></h3><p><strong>Germline EGFR T790M mutation and lung cancer risk</strong><em>Science（2026-09-17）</em></p><p>多数肺癌与烟草相关，家族性与非吸烟相关肺癌的遗传风险长期不清。LoPiccolo、Micheletti 等（56 位作者）在<strong>超过 330 万人</strong>中分析发现，胚系 <em>EGFR</em> T790M 变异与肺癌风险显著相关：对另外 17 种癌症<strong>无</strong>风险升高，且与多基因风险评分<strong>无</strong>交互。该风险<strong>超过吸烟所赋予的风险</strong>，在从不吸烟者中高出数倍。全球地理与祖源分析显示，T790M 在美国人群中的携带率高于英国/爱尔兰裔人群，源于约 <strong>200–225 年前</strong>一次美国南部阿巴拉契亚（Southern Appalachian）地区的<strong>奠基者事件</strong>，波及英裔、爱尔兰裔与非洲裔人群。识别高风险携带者可支撑靶向基因检测与筛查策略。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec0473" target="_blank" rel="noreferrer">10.1126/science.aec0473</a></p><h3 id="⚛️-双微波缀饰把超冷极性分子气体的损耗压低逾一万倍" tabindex="-1">⚛️ 双微波缀饰把超冷极性分子气体的损耗压低逾一万倍 <a class="header-anchor" href="#⚛️-双微波缀饰把超冷极性分子气体的损耗压低逾一万倍" aria-label="Permalink to &quot;⚛️ 双微波缀饰把超冷极性分子气体的损耗压低逾一万倍&quot;">​</a></h3><p><strong>Extreme loss suppression in an ultracold molecular gas with widely tunable dipolar interactions</strong><em>Science（2026-09-17）</em></p><p>超冷极性分子有望造出奇异量子物态，但长寿命、强偶极相互作用的分子体样品一直难以实现。Yuan、Zhang、Bigagli 等（8 位作者）实现了碰撞稳定的超冷基态分子气体，寿命达<strong>数秒</strong>：借助<strong>双微波缀饰（double-microwave dressing）</strong>，把非弹性二体损耗压低 <strong>&gt;10,000 倍</strong>、三体损耗压低 <strong>&gt;1,000 倍</strong>。关键的是，损耗抑制在很宽的偶极相互作用范围内都成立，可<strong>连续调谐偶极长度</strong>从 <strong>−21,000 至 12,000 <em>a₀</em></strong>（<em>a₀</em> 为玻尔半径）。结合近期实现的双极性分子玻色—爱因斯坦凝聚，这为探索强偶极量子液体打开了大门。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz0521" target="_blank" rel="noreferrer">10.1126/science.adz0521</a></p><h3 id="🩸-脾脏过滤活化血小板-维持全身血小板的静息状态" tabindex="-1">🩸 脾脏过滤活化血小板，维持全身血小板的静息状态 <a class="header-anchor" href="#🩸-脾脏过滤活化血小板-维持全身血小板的静息状态" aria-label="Permalink to &quot;🩸 脾脏过滤活化血小板，维持全身血小板的静息状态&quot;">​</a></h3><p><strong>Splenic regulation of systemic platelet activation state</strong><em>Science（2026-09-17）</em></p><p>血小板既防失血又编排炎症，但对抗全身性血小板活化的生理机制此前定义不清。Laun、Leunig 等（37 位作者）在小鼠中发现，<strong>脾脏</strong>在血栓与炎症条件下<strong>过滤活化的血小板</strong>，通过维持血小板静息来限制病理。机制上：脾红髓中细胞外基质成分经 <strong>GPVI</strong> 依赖途径活化血小板，与静息血小板中由 <strong>perlecan</strong> 触发的 <strong>G6b-B ITIM 信号</strong>相抗衡，从而允许血小板再循环；而预活化血小板中的阈值活化信号可<strong>压倒</strong>这种抑制，经 inside-out 信号与 <strong>β1-整合素</strong>结合导致被脾脏捕获。脾脏由此成为血小板反应性与血栓炎症风险的调节器。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec7230" target="_blank" rel="noreferrer">10.1126/science.aec7230</a></p><h3 id="🧠-自闭症风险突变小鼠的转录组分类-前额叶呈现两种对立状态" tabindex="-1">🧠 自闭症风险突变小鼠的转录组分类：前额叶呈现两种对立状态 <a class="header-anchor" href="#🧠-自闭症风险突变小鼠的转录组分类-前额叶呈现两种对立状态" aria-label="Permalink to &quot;🧠 自闭症风险突变小鼠的转录组分类：前额叶呈现两种对立状态&quot;">​</a></h3><p><strong>Transcriptome-based classification in mice with ASD-risk mutations</strong><em>Science（2026-09-17）</em></p><p>自闭症谱系障碍（ASD）遗传性强，人类遗传学研究已识别 &gt;1200 个风险基因。Roh、Jun 等（27 位作者）报告了一个<strong>性别平衡</strong>的前额叶转录组图谱：来自携带 ASD 风险突变的 <strong>17 个小鼠品系共 1,008 份</strong> RNA-seq 样本。分析识别出<strong>两种相反的转录组状态</strong>，两组在性别偏倚、区域特异性、发育稳定性、细胞类型重塑以及对<strong>氟西汀与锂</strong>的响应上各不相同。单核 RNA-seq 显示第 1 组比第 2 组有更广泛的细胞类型重塑，细胞类型特异模块间的相互关联与整体转录组特征一致。该框架可对独立小鼠品系分类，识别出具有保守突触方向性的亚组，支撑分子分层。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz6688" target="_blank" rel="noreferrer">10.1126/science.adz6688</a></p><h3 id="🌙-嫦娥六号撞击玻璃中发现常温稳定的天然月球-γ-fe-与磁涡旋态" tabindex="-1">🌙 嫦娥六号撞击玻璃中发现常温稳定的天然月球 γ-Fe 与磁涡旋态 <a class="header-anchor" href="#🌙-嫦娥六号撞击玻璃中发现常温稳定的天然月球-γ-fe-与磁涡旋态" aria-label="Permalink to &quot;🌙 嫦娥六号撞击玻璃中发现常温稳定的天然月球 γ-Fe 与磁涡旋态&quot;">​</a></h3><p><strong>Magnetic vortex state of natural lunar γ-Fe</strong><em>PNAS（2026-09-16）</em></p><p>月球表面 α-Fe 与 Fe-Ni 合金广布，是月壳剩磁的主要载体；而金属 <strong>γ-Fe</strong> 只在高温稳定，此前从未在月球样品中被记录。Liu、Jin 等（15 位作者）在来自<strong>南极—艾特肯盆地</strong>的<strong>嫦娥六号撞击玻璃碎片</strong>中，鉴定出以<strong>纳米级颗粒</strong>形式保存的常温稳定 γ-Fe。<strong>电子全息（electron holography）<strong>分析显示这些 γ-Fe 颗粒具有</strong>磁涡旋畴态</strong>。据此提出：γ-Fe 需在月表温度下形成并保存，必须同时具备痕量 γ 相稳定元素<strong>与</strong>月球撞击过程中的<strong>极快速淬火</strong>。该发现为理解月球核心发电机的演化与撞击诱导的磁记录机制提供了基础。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2608395123" target="_blank" rel="noreferrer">10.1073/pnas.2608395123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="♟️-技能水平越高-冻结的棋类-transformer-越调用更深的注意力层" tabindex="-1">♟️ 技能水平越高，冻结的棋类 Transformer 越调用更深的注意力层 <a class="header-anchor" href="#♟️-技能水平越高-冻结的棋类-transformer-越调用更深的注意力层" aria-label="Permalink to &quot;♟️ 技能水平越高，冻结的棋类 Transformer 越调用更深的注意力层&quot;">​</a></h3><p><strong>Increasing Skill Level Recruits Deeper Attention Layers in a Frozen Chess Transformer</strong><em>arXiv（2026-09-20）</em></p><p>Maia-3 棋类 Transformer 把 Elo（竞技棋力）作为<strong>输入</strong>喂给预训练网络，因而能在<strong>不改权重</strong>的前提下改变网络被条件化的技能水平。David Litman 在 Elo <strong>700–2500</strong> 的每一档消融<strong>每一个注意力头</strong>，发现：1）技能升高使计算的<strong>因果质心单调地移向更深层</strong>，对所测每种棋子与走法类型都成立；2）这种深度迁移对<strong>特定战术（尤以马的双叉 knight fork）<strong>远强于其它走法；3）迁移的实质是</strong>更深层被招募承担更专门的计算</strong>，而一个共享的<strong>浅层头</strong>贡献大致不变。结果或可揭示条件输入如何在更大 Transformer 中重新分配计算。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.23917" target="_blank" rel="noreferrer">2609.23917</a></p><h3 id="🔍-circuit-diff-用事实编辑干预定位归因图中的知识" tabindex="-1">🔍 Circuit-Diff：用事实编辑干预定位归因图中的知识 <a class="header-anchor" href="#🔍-circuit-diff-用事实编辑干预定位归因图中的知识" aria-label="Permalink to &quot;🔍 Circuit-Diff：用事实编辑干预定位归因图中的知识&quot;">​</a></h3><p><strong>Circuit-Diff: Factual Edit-based Intervention Method for Localizing Knowledge in Attribution Graphs</strong><em>arXiv（2026-09-20）</em></p><p>机械可解释性把特征视为网络基本单元、把电路视为执行计算的加权子图。由于单个神经元具有多义性，研究者用<strong>跨层转码器（CLT）<strong>近似电路并生成</strong>归因图</strong>；但图节点是<strong>未标注特征</strong>，读图需先剪枝再手工推断每个存活节点的含义。Edward G. Friedman 与 Xiangchen Song 提出 <strong>Circuit-Diff</strong>：对模型本身施加<strong>低秩事实编辑</strong>，把归因图中<strong>角色随该编辑而改变</strong>的特征视为与被编辑知识相关。在所考察的编辑上，被标记节点<strong>不只是</strong>对象 token 的检测器——从 CLT 公开的特征面板读出，它们还包含<strong>旧/新对象的历史、地理与关联特征</strong>。作者形式化了该方法，测量编辑后冻结 CLT 的可靠性，并在<strong>至多 24 个 CounterFact 编辑</strong>上通过打补丁<strong>因果检验</strong>所选节点。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.23892" target="_blank" rel="noreferrer">2609.23892</a></p><h3 id="💰-智能体总成本-多智能体-llm-工作流中记忆注入成本的精确归因" tabindex="-1">💰 智能体总成本：多智能体 LLM 工作流中记忆注入成本的精确归因 <a class="header-anchor" href="#💰-智能体总成本-多智能体-llm-工作流中记忆注入成本的精确归因" aria-label="Permalink to &quot;💰 智能体总成本：多智能体 LLM 工作流中记忆注入成本的精确归因&quot;">​</a></h3><p><strong>Total Cost of Agency: Exact Attribution of Memory Injection Cost in Multi-Agent LLM Workflows</strong><em>arXiv（2026-09-20）</em></p><p>多智能体 LLM 工作流的每个节点都从记忆检索上下文并注入提示，这些注入 token 按与系统提示、用户查询相同的单价计费；而生产可观测性工具只报总 token 成本，<strong>不区分节点生成的 tokens 与被喂给它的 tokens</strong>，于是这部分账单对付款团队<strong>不可见</strong>。Singh、Priyam、Bhowmick 提出 <strong>TCA（Total Cost of Agency）</strong>：把工作流成本分解为基础提示、推理、<strong>记忆注入</strong>、未命中惩罚与上下文累积五个分量，并给出<strong>精确归因方法</strong>——用两遍、不计费的 token 计数直接测量注入 tokens，而非用词数代理估计。在 <strong>200 个任务</strong>的企业级基准上对真实模型 API 运行：记忆注入占<strong>优化器可作用的变动成本的 13.6%</strong>、约<strong>全部计费成本的 12%</strong>，其份额从深度 1 的<strong>结构性零</strong>升至深度 6 的 <strong>27.6%</strong>；在所测范围内注入 tokens 随深度<strong>线性增长（R²=0.9974）</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.23790" target="_blank" rel="noreferrer">2609.23790</a></p><h3 id="📄-会改文档的智能体-对已归档-pdf-的智能体伪造测量与非智能体对照" tabindex="-1">📄 会改文档的智能体：对已归档 PDF 的智能体伪造测量与非智能体对照 <a class="header-anchor" href="#📄-会改文档的智能体-对已归档-pdf-的智能体伪造测量与非智能体对照" aria-label="Permalink to &quot;📄 会改文档的智能体：对已归档 PDF 的智能体伪造测量与非智能体对照&quot;">​</a></h3><p><strong>Agents That Edit Documents: Measuring Agentic PDF Forgery Against a Non-Agentic Control</strong><em>arXiv（2026-09-20）</em></p><p>AI 智能体已能自主完成多步计算机任务，而这种自主性同样可供有害任务使用——对以归档 PDF 为证据的依赖方（保险、放贷、审计）意味着什么？Simiao Ren 等提出 <strong>AgentForge-Bench</strong>：让一个现成编码智能体驱动 <strong>7 个开源权重模型</strong>，配 shell 与标准 Python PDF 栈，仅凭<strong>一句意图</strong>就改动一份真实归档财务文件中的某个<strong>金额、日期或地址</strong>，并用<strong>规则而非模型</strong>评分。在 <strong>1,750 个格</strong>中，1,419 个（<strong>81.1%</strong>）通过验证器，808 个（<strong>46.2%</strong>）还通过更严格的过滤（可见、局部、字体匹配、<strong>全文原值消失</strong>）。无模型的确定性脚本解出 125 份文档中的 98 份，智能体解出 124 份，且没有一份是脚本单独能解的。智能体把 <strong>41% 的错误编辑误报为已完成</strong>，<strong>没有任何模型拒绝</strong>，最便宜的已验证伪造仅需 <strong>2.4 美分</strong>。原始比率把威胁<strong>高估约一倍</strong>，严格比率依然巨大。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.23953" target="_blank" rel="noreferrer">2609.23953</a></p><h3 id="📊-evalstats-小样本-ai-评估中-llm-裁判统计的正确做法" tabindex="-1">📊 evalstats：小样本 AI 评估中 LLM 裁判统计的正确做法 <a class="header-anchor" href="#📊-evalstats-小样本-ai-评估中-llm-裁判统计的正确做法" aria-label="Permalink to &quot;📊 evalstats：小样本 AI 评估中 LLM 裁判统计的正确做法&quot;">​</a></h3><p><strong>How to Run Statistics over LLM Judges and Trust the Results: Calibrated Inference for Small-Sample AI Evaluation with evalstats</strong><em>arXiv（2026-09-20）</em></p><p>越来越多研究以 LLM 裁判分数与小样本评估为显著性结论的依据，但缺乏良好校准的置信区间、假设检验与裁判偏差校正时，这些结论并不可靠。Ian Arawjo 的贡献之一是发现：直接对<strong>原始 LLM 裁判分数</strong>做统计会导致<strong>假阳性膨胀</strong>——反直觉的是，对许多评审者间一致性指标，假阳性风险在人类—LLM <strong>&quot;几乎完美一致&quot;<strong>时</strong>达到峰值</strong>。作者给出混合人—AI 裁判设计统计分析的方法指引与工具，并基于<strong>预测驱动推断（PPI）<strong>实现 <strong>9 种假设检验</strong>，其中包括已知</strong>首批</strong>针对四种秩检验（Wilcoxon 符号秩、Mann-Whitney U 及其 omnibus 变体）的 PPI 校正；为在人类标注校准集很小时让 PPI++ 保持稳定，引入 <strong>bootstrap 自适应</strong>变体。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.35815" target="_blank" rel="noreferrer">2609.35815</a></p><blockquote><p>📅 日期：2026-09-20 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 ｜ （第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const u=t(s,[["render",a]]);export{d as __pageData,u as default};
